(function(){const e=document.createElement("link").relList;if(e&&e.supports&&e.supports("modulepreload"))return;for(const i of document.querySelectorAll('link[rel="modulepreload"]'))n(i);new MutationObserver(i=>{for(const a of i)if(a.type==="childList")for(const r of a.addedNodes)r.tagName==="LINK"&&r.rel==="modulepreload"&&n(r)}).observe(document,{childList:!0,subtree:!0});function t(i){const a={};return i.integrity&&(a.integrity=i.integrity),i.referrerPolicy&&(a.referrerPolicy=i.referrerPolicy),i.crossOrigin==="use-credentials"?a.credentials="include":i.crossOrigin==="anonymous"?a.credentials="omit":a.credentials="same-origin",a}function n(i){if(i.ep)return;i.ep=!0;const a=t(i);fetch(i.href,a)}})();const li={eyebrow:"交互式硬件档案 · 001",title:["一束光，如何","成为一段","可读信号"],lead:"三层板叠在一起，才构成一次完整测量：激光头出光与收光，顶板把微弱信号放大并数字化，底板负责时序、供电与传输。",hint:"拖动旋转 · 滚轮缩放 · 点击板层或区域",chain:[{n:"02",title:"激光头",note:"出光 / 收光"},{n:"03",title:"顶板",note:"放大 · 滤波 · 数字化"},{n:"01",title:"底板",note:"调度 · 供电 · 传输"}],readme:[{k:"这是什么",v:"一台三层堆叠的激光传感硬件。三层板各自负责光学、模拟与数字，中间用排针和同轴线连接。三块板都是双面板，元件分布在正反两面。"},{k:"怎么看",v:"先点左侧板层（或直接点模型上的板），再点板面上的发光标记。点中的区域如果在板的背面，板子会自动翻过来；也可以按「翻到背面」自己翻。拖动可以从下方观察。"}]},Pn={laser:{index:"02",name:"激光头",subtitle:"发光、收光与光电转换",lead:"激光头是唯一接触被测表面的部分：一束光从这里出去，回光也从这里回来，并在同一块小板上完成光电转换。",note:"14 × 14 mm · 单板 1.6 mm"},top:{index:"03",name:"顶板",subtitle:"微弱信号调理与高精度采集",lead:"顶板处理的是最容易丢失的那一段：把光电流放大、滤掉高频毛刺，再交给 ADC 变成可以计算的数字。",note:"50 × 50 mm · 单板 1.6 mm"},bottom:{index:"01",name:"底板",subtitle:"系统控制、供电、存储与通信",lead:"底板是整机的指挥部：它决定什么时候发光、什么时候采样，也负责把电能和数据送到该去的地方。",note:"50 × 50 mm · 单板 1.6 mm"}},vr={"laser-z0":{title:"激光二极管与光机结构",tag:"光学起点",purpose:"发光和收光都发生在这里。铜色的 TO-56 金属壳固定激光二极管，顶部的镜片让光按设计方向进出。",why:"光路一旦偏移、松动，或者漏进环境光，接收到的能量就会变——而这个变化和被测对象毫无关系，会直接变成测量漂移。",how:"金属壳提供机械基准、散热和遮光；激光二极管把恒流变成稳定的光；回光沿同一光路进入探测器，避免发射与接收的光轴彼此错开。",impact:"把「光路稳定」从偶然条件变成可复现的工程条件，后级放大才有稳定的输入。",flow:"恒流驱动 → <b>激光二极管</b> → 出光 → 被测面 → 回光 → 探测器"},"laser-z1":{title:"驱动与阻抗匹配",tag:"光电转换接口",purpose:"激光头自带的一小片电路：把输入的驱动信号调整到二极管需要的工作点，并把回光信号整齐地送到顶板。",why:"激光头离主驱动电路有一段距离，线缆的寄生电感与电容会改变驱动波形；把匹配放在光头附近，这段不确定性就被关在最小的范围里。",how:"DFN 封装的小芯片与周围阻容构成匹配与偏置网络；两枚 IPEX 座把驱动和回光分别用同轴线送出去，射频与模拟各自走自己的通路。",impact:"让光头与主板之间变成一段确定的、可以整根更换的同轴通路，而不是一堆飞线。",flow:"顶板 → 同轴线 → <b>IPEX</b> → 匹配网络 → 激光二极管"},"top-z3":{title:"高精度采集",tag:"信号的数字化",purpose:"把调理好的模拟波形转换成主控能够计算、存储和回放的数字采样点。",why:"光电信号里真正有用的变化很细微。量化精度不够，波形的幅度、上升沿和细节会被台阶化——后面的算法再聪明，也无法把丢掉的信息恢复出来。",how:"TSSOP-38 封装的 8 通道 16 位 ADC 按稳定时钟对电压取样，为每个采样点分配一个数字值；基准与去耦网络保证相邻通道之间读数一致。",impact:"得到时间间隔明确、幅值可比较的数字波形，交给底板缓存、分析与传输。",flow:"调理后的电压 → <b>ADC 采样 / 量化</b> → 数字总线 → 底板"},"top-z1":{title:"激光驱动与光电前端",tag:"一进一出",purpose:"这一区同时负责两件事：让激光器稳定地亮，以及把回来的那一点光变成电压。",why:"如果光源自己忽明忽暗，接收端会把光源的波动误认为被测对象的变化；而回光非常微弱，从光到电压的转换必须在尽量短的路径上完成。",how:"恒流驱动环路不断比较设定值与实际电流并修正，让出光强度不随电池电压漂移；跨阻放大级把光电流变成电压，再由 RC 网络做低通，压掉高频毛刺。",impact:"给整机一条稳定的「照明基线」和一个干净的模拟入口——两者都不稳定，后面做得再精密也没有意义。",flow:"设定值 → <b>恒流环路</b> → 激光器 ｜ 回光 → 光电流 → <b>跨阻放大</b> → 低通"},"top-z0":{title:"模拟电源与稳压",tag:"供电地基",purpose:"把底板送来的电源再稳一次，生成运放和 ADC 需要的低噪声模拟轨。",why:"微弱的光电流信号对电源纹波极其敏感。数字电路每一次开关动作产生的毫伏级抖动，都会被后面的放大级原样放大，最后看起来就像是信号本身。",how:"SOT-223 封装的稳压芯片把输入压差降到合适范围，配合电感与多级去耦，把高频噪声挡在模拟区之外。",impact:"让放大级有足够的摆幅和干净的供电，也避免电源问题被误读成信号特征。",flow:"底板电源 → <b>稳压 / 滤波</b> → 模拟轨 → 前端与 ADC"},"top-z2":{title:"板间连接与信号分配",tag:"三层的枢纽",purpose:"顶板与底板、激光头之间的电源和模拟信号，从这里接入，再分流到各个功能区。",why:"三层结构里同一根电源线要同时服务数字和模拟负载。分配点选得不好，共地阻抗就会把数字噪声耦合进模拟回路——这类问题在原理图上完全看不出来。",how:"多组 2.54 mm 排针提供短而确定的连接路径；旁边的小封装芯片完成电平切换与信号缓冲；电源与地在入口处就分开走线。",impact:"让板间信号路径可预期，并在入口处就把噪声隔离掉。",flow:"底板 → <b>排针</b> → 分区供电 / 信号缓冲 → 各功能区"},"bottom-z0":{title:"电源输入与充电管理",tag:"能量入口",purpose:"USB-C 接入的 5 V 和电池电压，在这里被整理成三层板各自需要的电源轨。",why:"电池电压会随电量下滑，而激光驱动、模拟前端和数字电路对电压与噪声的要求并不相同。把未经处理的电源直接分给三层，电源的波动最后会被写进测量结果。",how:"USB-C 座接入外部供电，电源管理芯片完成充电与开关变换，电感与电容组成储能和滤波网络，保险丝在异常电流时切断回路，两颗 LED 指示充电与工作状态。",impact:"让满电和低电时表现一致，并给模拟前端留出干净的电源环境。",flow:"USB-C 5 V / 电池 → <b>充电与变换</b> → 数字轨 · 模拟轨 · 激光轨"},"bottom-z1":{title:"柔性排线座与板间互联",tag:"整机出口",purpose:"这里是整机对外的电气出口：两枚 1.25 mm 间距的 FPC 座和 2.54 mm 排针，把三层板与外部柔性排线连在一起。",why:"板与板之间如果靠飞线，装配一致性差，弯折几次就可能接触不良。用排线座和排针，把「连接」变成可以插拔、可以复现的零件。",how:"7P 1.25 mm FPC 座压住柔性排线的金手指；4P GH1.25 座引出电池或外部触点；2.54 mm 排针把电源、地和数字信号送到顶板与激光头。",impact:"让生产测试、固件维护和整机装配都有确定的接口，三层结构也因此可以拆开检修。",flow:"外部柔性排线 ↔ <b>FPC 座</b> ↔ 排针 ↔ 顶板 / 激光头"},"bottom-z2":{title:"主控与存储",tag:"调度中心",purpose:"整台设备的调度中心：安排何时发光、何时采样，把数字波形缓存下来，再通过 USB 或无线送出去。",why:"激光头、模拟前端和 ADC 各自只完成一个环节。必须有统一的时序，把「发光—采样—传输」串成一次完整测量，否则三层板只是三个互不相干的模块。",how:"QFN 封装的主控芯片负责时序与外设；旁边的晶振提供稳定时间基准；密集的去耦电容让每次开关动作不把噪声带上电源；Flash 保存程序与参数。",impact:"把分散的硬件动作变成可重复的产品流程，并把原始采样组织成上层应用能用的数据。",flow:"ADC 数据 → <b>主控缓冲 / 处理</b> → USB · 无线 · Flash"},"bottom-z3":{title:"按键与天线接口",tag:"现场操作",purpose:"两颗贴片按键负责复位与进入烧录模式，IPEX 座把射频能量送到天线。",why:"量产与维护都需要一个不拆机就能复位、能烧录的入口；无线连接则要求射频路径阻抗连续，否则传输距离和连接稳定性都会下降。",how:"按键直接拉低复位与启动引脚；IPEX 座与匹配网络构成确定的射频通路，布局上远离模拟区，减少射频与微弱信号之间的互扰。",impact:"让设备可以现场恢复、现场升级，并在没有线缆的情况下把测量结果送出去。",flow:"按键 → 复位 / 启动 ｜ 数据 → 射频 → <b>IPEX</b> → 天线"}},_h=[["01","旋转模型","按住拖动可以从任意方向观察元件、焊盘、排线与同轴接头。"],["02","选择板层","点击左侧列表或直接点模型上的板，进入单板聚焦。"],["03","点开区域","点击板面上的发光标记，右侧会展开这块区域在信号链里的作用。"],["04","回到全景","点击空白处或按 Esc，逐级退回单板与三层全景。"]];const _o="181",Ii={ROTATE:0,DOLLY:1,PAN:2},Di={ROTATE:0,PAN:1,DOLLY_PAN:2,DOLLY_ROTATE:3},vh=0,Jo=1,Mh=2,El=1,Tl=2,wn=3,In=0,Nt=1,Kt=2,Ln=0,Ui=1,Mr=2,Qo=3,ec=4,Sh=5,oi=100,yh=101,Eh=102,Th=103,Ah=104,wh=200,Rh=201,Ch=202,Ph=203,Sr=204,yr=205,Lh=206,Dh=207,Ih=208,Uh=209,Nh=210,Fh=211,Oh=212,kh=213,Bh=214,Er=0,Tr=1,Ar=2,ki=3,wr=4,Rr=5,Cr=6,Pr=7,vo=0,zh=1,Hh=2,Kn=0,Gh=1,Vh=2,Wh=3,Al=4,Xh=5,jh=6,qh=7,tc="attached",Yh="detached",wl=300,Bi=301,zi=302,Lr=303,Dr=304,ya=306,Hi=1e3,pn=1001,xa=1002,Ft=1003,Rl=1004,fs=1005,Ut=1006,ha=1007,Rn=1008,xn=1009,Cl=1010,Pl=1011,bs=1012,Mo=1013,di=1014,an=1015,Yi=1016,So=1017,yo=1018,_s=1020,Ll=35902,Dl=35899,Il=1021,Ul=1022,$t=1023,vs=1026,Ms=1027,Eo=1028,To=1029,Ao=1030,wo=1031,Ro=1033,da=33776,ua=33777,fa=33778,pa=33779,Ir=35840,Ur=35841,Nr=35842,Fr=35843,Or=36196,kr=37492,Br=37496,zr=37808,Hr=37809,Gr=37810,Vr=37811,Wr=37812,Xr=37813,jr=37814,qr=37815,Yr=37816,Kr=37817,Zr=37818,$r=37819,Jr=37820